import sys

d = sys.stdin.read().split()
n, sr, sc, tr, tc = map(int, d[:5])
INF = 10 ** 9
dist = {(r, c): INF for r in range(n) for c in range(n)}
dist[(sr, sc)] = 0
changed = True
while changed:
    changed = False
    for (r, c), v in list(dist.items()):
        if v == INF:
            continue
        for dr in (-2, -1, 1, 2):
            for dc in (-2, -1, 1, 2):
                if abs(dr) != abs(dc):
                    p = (r + dr, c + dc)
                    if p in dist and dist[p] > v + 1:
                        dist[p] = v + 1
                        changed = True
res = dist[(tr, tc)]
print(res if res < INF else -1)

